CREATE TABLE `prompt_config` (
  `id` int NOT NULL AUTO_INCREMENT,
  `project_id` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `prompt_type` enum('intent_recognition','table_selection','sql_generation','sql_error_recovery','data_interpretation','fluctuation_attribution','follow_up_handling','analysis_strategy_application') COLLATE utf8mb4_unicode_ci NOT NULL,
  `prompt_category` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `system_prompt` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `user_prompt_template` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `examples` json DEFAULT NULL,
  `temperature` float DEFAULT NULL,
  `max_tokens` int DEFAULT NULL,
  `enabled` tinyint(1) DEFAULT NULL,
  `created_by` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

